package common

import("fmt";"net/http";"net/url";"strings")
type ZulipAdapter struct{BaseURL,Email,APIKey string;Client *http.Client}
func(a ZulipAdapter)ParseEvent(payload map[string]any)(InboundEvent,error){message:=payload;if nested,ok:=payload["message"].(map[string]any);ok{message=nested};user:=fmt.Sprint(message["sender_email"]);if user=="<nil>"||user==""{user=fmt.Sprint(message["sender_id"])};if user=="<nil>"||user==""{return InboundEvent{},fmt.Errorf("Zulip message has no sender")};if message["type"]=="stream"{stream,_:=message["display_recipient"].(string);subject,_:=message["subject"].(string);if stream==""||subject==""{return InboundEvent{},fmt.Errorf("Zulip stream message has no stream or subject")};return InboundEvent{Platform:"zulip",UserID:user,ReplyTarget:stream,ReplyToID:subject,ReplyMode:"stream",ContentType:"text",Text:fmt.Sprint(message["content"])},nil};return InboundEvent{Platform:"zulip",UserID:user,ReplyMode:"direct",ContentType:"text",Text:fmt.Sprint(message["content"])},nil}
func(a ZulipAdapter)SendReply(event InboundEvent,reply OutboundReply)error{client:=a.Client;if client==nil{client=http.DefaultClient};for _,message:=range reply.Messages{form:=url.Values{};if event.ReplyMode=="stream"{form.Set("type","stream");form.Set("to",event.ReplyTarget);form.Set("subject",event.ReplyToID)}else{form.Set("type","direct");form.Set("to",event.UserID)};form.Set("content",message.Text);req,_:=http.NewRequest(http.MethodPost,strings.TrimRight(a.BaseURL,"/")+"/api/v1/messages",strings.NewReader(form.Encode()));req.SetBasicAuth(a.Email,a.APIKey);req.Header.Set("Content-Type","application/x-www-form-urlencoded");resp,err:=client.Do(req);if err!=nil{return err};resp.Body.Close();if resp.StatusCode/100!=2{return fmt.Errorf("Zulip API returned %s",resp.Status)}};return nil}
